import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_none_counts_as_unflagged():
    assert monitor_flag_rate([{"flagged": None}, {"flagged": True}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_last_duplicate_id_wins_before_sorting():
    events = parse_transcript_log(["x,9,1", "z,2,1", "a,3,0", "x,2,"])
    assert dedupe_transcripts(events) == [events[3], events[1], events[2]]


def test_log_whitespace_comments_and_flags():
    lines = ["", " \t", "  # ignore", " a , 1 , 1 ", " b , 2 , 0 ", " c , 3 ,  "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 3, "flagged": None},
    ]


@pytest.mark.parametrize("line", ["a,1", "a,1,0,extra", "a,no,1"])
def test_parse_error_counts_skipped_lines(line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# header", "a,1,1", " ", line])


def test_daily_counts_respect_range_and_include_zeros():
    events = parse_transcript_log(["a,0,1", "b,2,1", "c,2,1", "d,3,0", "e,4,1"])
    assert daily_flag_counts(events, 1, 3) == [0, 2, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_trailing_windows():
    assert flags_in_window([2, 3, 1], 0) == 0
    assert flags_in_window([2, 3, 1], 2) == 4
    assert flags_in_window([2, 3, 1], 5) == 6


def test_summary_uses_transcript_weights_and_calendar_days():
    groups = {
        "a": parse_transcript_log(["a,1,1"]),
        "b": parse_transcript_log(["b,4,1", "c,5,0"]),
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 2 / 3
    assert monitor_summary(groups, 4) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"empty": []}, 4) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ordering_and_empty_groups():
    groups = {"z": [{"flagged": False}], "c": [{"flagged": True}], "b": [], "a": [{"flagged": True}]}
    assert top_flagged_groups(groups, 8) == ["a", "c", "z"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", None), ("c", 1.0), ("z", 0.0)]


def test_streak_requires_consecutive_positive_days():
    assert longest_flag_streak([]) == 0
    assert longest_flag_streak([2, 0, 1, 3, -1, 1]) == 2
